import{_ as i,o as s,c as a,a2 as l}from"./chunks/framework.BZO4qERu.js";const t="/assets/heap-region.DgJQcwPl.png",n="/assets/heap-structure.DZeQ-1DI.png",p="/assets/new-delete.sYx38W4F.png",y=JSON.parse('{"title":"动态内存管理","description":"","frontmatter":{},"headers":[],"relativePath":"language/c/memory-operation.md","filePath":"language/c/memory-operation.md","lastUpdated":1781086744000}'),h={name:"language/c/memory-operation.md"};function d(k,e,r,o,c,E){return s(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="动态内存管理" tabindex="-1">动态内存管理 <a class="header-anchor" href="#动态内存管理" aria-label="Permalink to &quot;动态内存管理&quot;">​</a></h1><h2 id="malloc与free" tabindex="-1">malloc与free <a class="header-anchor" href="#malloc与free" aria-label="Permalink to &quot;malloc与free&quot;">​</a></h2><p>malloc与free是C语言标准库中的函数，用于动态内存分配与释放。</p><p><code>malloc</code></p><ul><li>C语言中的标准库函数，存在于头文件<code>&lt;stdlib.h&gt;</code>中。</li><li>函数声明为： <code>void* malloc(size_t size)</code>。</li><li>作用：为开辟一块<code>size</code>大小的内存空间，如果分配成功则返回指向这块空间的指针，分配失败则返回空指针NULL。</li></ul><p><code>free</code></p><ul><li>也是C语言中的标准库函数，存在与头文件<code>&lt;stdlib.h&gt;</code>中。</li><li>函数声明为： <code>void free(void *ptr)</code>。</li><li>作用：将分配给指针ptr指向区域的内存空间进行回收。</li><li>这里的ptr必须已经被<code>malloc</code>或者<code>realloc</code>,<code>calloc</code>类型的函数调用过，否则会产生未定义行为。</li><li>如果free(ptr)已经被调用过，重复调用也会产生未定义行为。</li><li>如果ptr为NULL，不执行任何操作。</li></ul><h3 id="实现原理" tabindex="-1">实现原理 <a class="header-anchor" href="#实现原理" aria-label="Permalink to &quot;实现原理&quot;">​</a></h3><p>malloc以及free可以有多种实现方式，并且没有一种方法是完美的，因为我们需要在速度，开销和避免碎片/空间有效性之间做出折衷。</p><p>简单来说，我们把进程中一个从x到y的内存区域称为「堆」。所有<code>malloc</code>函数分配的内存会存在这个区域中。<code>malloc</code>会维护一个数据结构，我们干脆简化为一个链表，其中含有内存块的「元信息」，以及真正存放数据的「内存块区域」。当我们调用<code>malloc</code>的时候，它会遍历这个列表寻找有没有合适大小的未分配的内存块，如果有的话，将其指针返回，并且标记这块内存已经被分配了；如果没有的话，它会使用<code>sbrk()</code>这个系统调用来扩大堆区域，也就是说增加y的值（注意这里<code>sbrk</code>一定是一个系统调用，我们不可能从用户空间去改变堆的大小）。并且，这里的y是不能无限制增长的，在Linux中有一个变量<code>RLIMIT_DATA</code>用来限制进程中数据区（data segment，包括初始化数据，未初始化数据以及堆）的最大值。当堆区增长到最大限度后，再调用<code>sbrk</code>就会报<code>ENOMEM</code>错误。 <img src="'+t+'" alt="heap-region"><img src="'+n+'" alt="heap-structure"></p><p>我们还要注意，在Linux实现中，当malloc申请的内存超过<code>MMAP_THRESHOLD</code>时，它就不会使用<code>sbrk</code>去增加堆大小分配内存了，而是直接使用<code>mmap</code>系统调用做一个私有匿名映射，为其分配内存。这里的<code>MMAP_THRESHOLD</code>默认为128KB，并且可以通过<code>mallopt</code>系统调用去修改其大小。这里我们没有直接堆内存，因此内存分配大小不会受到<code>RLIMIT_DATA</code>的影响。</p><p>另一方面，<code>free(void *ptr)</code>在实现的时候，会找到ptr所对应的，之前所分配的内存块，将它标记为未分配，并且加入「未分配链表」中，同时还会进行一些空闲内存整合的操作，来减小内存碎片。</p><h2 id="new和delete" tabindex="-1">new和delete <a class="header-anchor" href="#new和delete" aria-label="Permalink to &quot;new和delete&quot;">​</a></h2><p>在C语言中，我们写程序时，总是会有动态开辟内存的需求，每到这个时候我们就会想到用malloc/free 去从堆里面动态申请出来一段内存给我们用。但对这一块申请出来的内存，往往还需要我们对它进行稍许的“加工”后即初始化 才能为我们所用，虽然C语言为我们提供了<code>calloc</code>来开辟一段初始化好（0）的一段内存，但面对象中各是各样的数据成员初始化，它同样束手无策。同时，为了保持良好的编程习惯，我们也都应该对申请出来的内存作手动进行初始化。 对此，这常常让我们感到一丝繁琐，于是到了C++中就有了<code>new/delete, new[]/delete[]</code> ，用它们便可实现动态的内存管理。</p><p>在C++中，把int 、char..等内置类型的变量也看作对象，它们也是存在构造函数和析构函数的，只是通常对它们，系统调用了默认的构造函数来初始化以及默认的析构（编译器优化）。所以new int、new int(3)看起来和普通的定义好像没什么区别。 但对于自定义类型的对象，此种方式在创建对象的同时，还会将对象初始化好；于是new/delete、new []/delete []方式管理内存相对于malloc/free的方式管理的优势就体现出来了，因为它们能保证对象一被创建出来便被初始化，出了作用域便被自动清理。</p><p>new/delete 是C++中的「关键字」，需要编译器支持。他们的使用格式入下： <img src="'+p+`" alt="new-delete"></p><p>new会先调用operator new函数，申请足够的内存（通常底层使用malloc实现）。然后调用类型的构造函数，初始化成员变量，最后返回自定义类型指针。delete先调用析构函数，然后调用operator delete函数释放内存（通常底层使用free实现）。</p><p>这里提到的<code>operator new</code>, <code>operator delete</code>是C++标准库函数。而 new/delete 关键字真正的实现就是依赖于那几个函数的。在C++中我们称之为‘placement版’内存管理接口。</p><div class="language-c++ vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c++</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> operator</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> new</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);　　</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> operator</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void*</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> operator</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> []</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);　　</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">void</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> operator</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> delete[]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">size_t</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>所以，我们可以得出 new/delete 关键字的执行步骤大致如下：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">new </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator new </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> malloc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 构造函数</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  //初始化一个对象时</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">new </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator new</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">[]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator new </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> malloc </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 构造函数</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //初始化多个对象时</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">delete </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 析构函数 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator delete </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> free</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //删除单个对象时</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">delete </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 析构函数 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">[]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> operator delete </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> free</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> //删除多个对象时</span></span></code></pre></div><p>为了避免上述表示产生混乱，在此作出解释：operator new 底层是由 malloc 实现的，operator delete 底层是由 free 实现的（也不是必须，这其实取决于 C++标准库 具体是如何去实现这几个函数的），但是构造函数和析构函数并不是包含在operator函数中的，在new关键词中构造函数是在operator函数之后执行的，在delete关键字中析构函数是在operator函数之前执行的。</p><p>另外，我们发现，由于在delete的时候我们要执行析构函数，如果是 delete[] 的话，我们要对所有对象依次执行析构函数，所以我们必须要知道「对象的数量」。但是我们发现在 delete[] 语法中只需传入指针，无需传入数量，那么它是如何知道对象的数目呢？</p><p>这其实是因为，在使用 new[] 关键字创建对象时，编译器会首先用4个字节「保存对象数量」，然后在后移4个字节的地方才会调用 operator new[]函数，这样可以保证返回指针的「前面4个字节」存储的是对象数量，也就是说 delete[] 关键字 在删除对象的时候，只需要读取指针对象「之前的4个字节」即可得到对象数量，进行析构处理，然后再调用 operator delete[] 进行内存的释放。</p><p>同时我们还要注意，并不是对于每一个 new[] 都会开辟这么4个字节去存储对象数量。对于没有显示定义析构函数的对象类型，例如 int, char这种，编译器就会进行优化，不额外开启内存存储对象数量，因为这些对象并不需要依次调用析构函数，所以直接无脑释放就行了。</p><p>所以根据以上，我们必须注意：new一定要和delete配套使用，new[] 一定要和 delete[] 配套使用。</p><h2 id="malloc-free-与-new-delete-区别和联系" tabindex="-1">malloc/free 与 new/delete 区别和联系 <a class="header-anchor" href="#malloc-free-与-new-delete-区别和联系" aria-label="Permalink to &quot;malloc/free 与 new/delete 区别和联系&quot;">​</a></h2><ul><li>malloc/free只是动态分配内存空间/释放空间。而new/delete除了分配空间还会调用构造函数和析构函数进行初始化与清理（清理成员）。</li><li>它们都是动态管理内存的入口。</li><li>malloc/free是C/C++标准库的函数，new/delete是C++操作符。</li><li>malloc/free需要手动计算类型大小且返回值为void*，new/delete可自动计算类型的大小，返回对应类型的指针。</li><li>malloc/free管理内存失败会返回NULL，new/delete等的方式管理内存失败会抛出异常。</li></ul>`,28)])])}const m=i(h,[["render",d]]);export{y as __pageData,m as default};
